<script lang="ts">
 import { enhance } from '$app/forms';
 import type { Booking } from './+page.server';
 let { data, form } = $props();
 let selected=$state('');let editing=$state<Booking|null>(null);let saving=$state(false);
 const year=$derived(Number(data.month.split('-')[0]));const month=$derived(Number(data.month.split('-')[1])-1);
 const days=$derived(new Date(Date.UTC(year,month+1,0)).getUTCDate());const offset=$derived((new Date(Date.UTC(year,month,1)).getUTCDay()+6)%7);
 const monthTitle=$derived(new Intl.DateTimeFormat('en',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(Date.UTC(year,month,1))));
 const dayKey=(day:number)=>`${data.month}-${String(day).padStart(2,'0')}`;
 function monthHref(direction:number){return '/admin?month='+new Date(Date.UTC(year,month+direction,1)).toISOString().slice(0,7);}
 function choose(date:string){selected=date;editing=null;}
 function edit(booking:Booking){selected=booking.booking_date||'undated';editing=booking;}
 const confirmed=$derived(data.calendarBookings.filter(b=>b.status==='confirmed'&&b.booking_date?.startsWith(data.month)).length);const requests=$derived(data.bookings.filter(b=>b.status==='requested').length);
 const maxVisits=$derived(Math.max(1,...(data.stats?.daily||[]).map(d=>d.visits)));
</script>
<svelte:head><title>Studio admin | InceptChange</title><meta name="robots" content="noindex,nofollow,noarchive"/></svelte:head>
<section class="section admin-panel">
 <div class="admin-top"><div><p class="eyebrow"><span class="dot"></span> INCEPTCHANGE · STUDIO ADMIN</p><h1>Welcome to <span class="serif">IdeaBay.</span></h1><p>{data.admin} · All dates in Sri Lanka time</p></div><form method="POST" action="?/logout"><button class="button dark">Sign out ↗</button></form></div>
 <div class="month-navigation"><a href={monthHref(-1)} aria-label="Previous month">←</a><h2>{monthTitle}</h2><a href={monthHref(1)} aria-label="Next month">→</a></div>
 {#if data.issue}<p class="admin-notice" role="alert">{data.issue}</p>{/if}
 <div class="metrics"><div><span>Visits this month</span><strong>{data.stats?data.stats.visits:'—'}</strong><small>Distinct browser sessions</small></div><div><span>Page views</span><strong>{data.stats?data.stats.pageviews:'—'}</strong><small>Public pages only</small></div><div><span>Confirmed bookings</span><strong>{data.issue?'—':confirmed}</strong><small>Studio and project bookings</small></div><div><span>Requests on this page</span><strong>{data.issue?'—':requests}</strong><small>Awaiting your review</small></div></div>
 <div class="admin-grid">
  <section class="admin-card"><div class="card-heading"><h2>Studio calendar</h2><span>IdeaBay</span></div><div class="legend"><span>● Confirmed</span><span>◉ Blocked</span><span>○ Requested</span></div>
   <div class="admin-calendar">{#each ['Mon','Tue','Wed','Thu','Fri','Sat','Sun'] as weekday}<span>{weekday}</span>{/each}{#each Array(offset) as _}<i></i>{/each}{#each Array(days) as _,i}{@const date=dayKey(i+1)}{@const entries=data.calendarBookings.filter(b=>b.booking_date===date&&b.status!=='cancelled')}<button class:chosen={selected===date} class:reserved={entries.some(b=>b.status==='confirmed'&&b.is_studio)} class:blocked={entries.some(b=>b.status==='blocked')} onclick={()=>choose(date)} aria-label={`${date}: ${entries.map(b=>b.status).join(', ')||'No bookings'}`} aria-pressed={selected===date}><strong>{i+1}</strong><small>{entries.some(b=>b.status==='blocked')?'Blocked':entries.some(b=>b.status==='confirmed'&&b.is_studio)?'Booked':entries.length?`${entries.length} request${entries.length>1?'s':''}`:''}</small></button>{/each}</div>
   <p class="admin-help">Choose a date to add a booking or block the studio. Confirmed bookings and blocks remove the full day from the public calendar.</p>
   {#if selected}<div class="booking-editor"><h3>{editing?'Edit calendar entry':'New calendar entry'} · {selected}</h3>
    {#key `${selected}-${editing?.id||'new'}`}
    <form method="POST" action="?/save" use:enhance={()=>{saving=true;return async({update})=>{await update({reset:false});saving=false;};}}>
     <input type="hidden" name="id" value={editing?.id||''}/><input type="hidden" name="date_description" value={editing?.date_description||selected}/>
     <div class="fields"><label>Booking type<select name="is_studio" value={editing?String(editing.is_studio):'true'}><option value="true">Studio</option><option value="false">Other project</option></select></label><label>Booking date<input type="date" name="booking_date" value={editing?.booking_date||(selected==='undated'?'':selected)}/></label><label>Location<input name="location" value={editing?.location||'IdeaBay — InceptChange studio'} maxlength="3000"/></label><label>Name / block reason<input name="name" value={editing?.name||''} required maxlength="150"/></label><label>Status<select name="status" value={editing?.status||'confirmed'}><option value="requested">Requested</option><option value="confirmed">Confirmed</option><option value="blocked">Blocked</option><option value="completed">Completed / done</option><option value="cancelled">Cancelled / released</option></select></label><label>Email<input type="email" name="email" value={editing?.email||''} maxlength="254"/></label><label>Service<input name="service" value={editing?.service||''} maxlength="1000"/></label><label>Start time<input type="time" name="start_time" value={editing?.start_time?.slice(0,5)||''}/></label><label>Duration<input name="duration" value={editing?.duration||''} maxlength="100" placeholder="e.g. 3 hours"/></label></div><label>Notes<textarea name="notes" rows="3" maxlength="5000">{editing?.notes||''}</textarea></label><button class="button dark" disabled={saving||!!data.issue}>{saving?'Saving…':'Save calendar entry ↗'}</button>
    </form>{/key}
   </div>{/if}
   {#if form?.message}<p class="admin-notice" role="status">{form.message}</p>{/if}
  </section>
  <section class="admin-card"><div class="card-heading"><h2>Monthly traffic</h2><span>Sessions</span></div>
   {#if data.stats?.daily.length}<div class="traffic-chart" aria-label="Daily visits">{#each data.stats.daily as day}<div title={`${day.day}: ${day.visits} visits, ${day.pageviews} views`}><span style:height={`${Math.max(3,day.visits/maxVisits*120)}px`}></span><small>{Number(day.day.slice(-2))}</small></div>{/each}</div><details><summary>View daily counts</summary><table><thead><tr><th>Date</th><th>Visits</th><th>Views</th></tr></thead><tbody>{#each data.stats.daily as day}<tr><td>{day.day}</td><td>{day.visits}</td><td>{day.pageviews}</td></tr>{/each}</tbody></table></details>{:else}<p class="empty">{data.issue?'Traffic data is unavailable.':'No visits recorded for this month yet.'}</p>{/if}
   <h3 class="pages-heading">Top pages</h3>{#each data.stats?.pages||[] as item}<div class="page-row"><span>{item.path}</span><strong>{item.views}</strong></div>{/each}
   <p class="admin-help">A visit is a browser session with a 30-minute inactivity window. These are estimates; bots and blocked scripts can affect counts. Tracking begins after database setup.</p>
  </section>
 </div>
 <section class="admin-card bookings-list"><div class="card-heading"><h2>All bookings & requests</h2><span>Page {data.listPage} · {data.bookings.length} entries</span></div>{#if data.bookings.length}<div class="table-scroll"><table><thead><tr><th>Date</th><th>Customer</th><th>Service / notes</th><th>Status</th><th></th></tr></thead><tbody>{#each data.bookings as booking}<tr><td>{booking.booking_date||booking.date_description||'Date undecided'}<small>{booking.start_time?.slice(0,5)||''}</small></td><td>{booking.name}<small>{booking.email}</small></td><td>{booking.service}<small>{booking.is_studio?'Studio':'Other project'} · {booking.location}<br/>Email: {booking.email_status||'unknown'}</small><small>{booking.notes}</small></td><td><span class="status" class:confirmed={booking.status==='confirmed'}>{booking.status}</span></td><td><button class="edit-button" onclick={()=>edit(booking)}>Edit ↗</button>{#if booking.status!=='completed'}<form method="POST" action="?/complete" use:enhance><input type="hidden" name="id" value={booking.id}/><button class="edit-button">Mark done ✓</button></form>{/if}<form method="POST" action="?/delete" use:enhance onsubmit={(event)=>{if(!confirm('Delete this booking permanently?'))event.preventDefault();}}><input type="hidden" name="id" value={booking.id}/><input type="hidden" name="confirm" value="yes"/><button class="edit-button">Delete ×</button></form></td></tr>{/each}</tbody></table></div>{:else}<p class="empty">No bookings recorded yet.</p>{/if}<div class="month-navigation">{#if data.listPage>1}<a href={`/admin?month=${data.month}&listPage=${data.listPage-1}`}>← Newer</a>{/if}{#if data.hasMore}<a href={`/admin?month=${data.month}&listPage=${data.listPage+1}`}>Older →</a>{/if}</div><p class="admin-help">Changing status does not send a customer email. Confirm details directly with the customer.</p></section>
</section>
<style>
