r{border-top:1px solid var(--line);margin-top:25px;padding-top:25px}.booking-editor h3{font-size:15px;margin-bottom:20px}.fields{display:grid;grid-template-columns:1fr 1fr;gap:0 15px}.admin-notice{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:16px;font-size:13px;line-height:1.7;margin:20px 0}.traffic-chart{display:flex;gap:5px;align-items:flex-end;height:165px;padding:10px 0;border-bottom:1px solid var(--line)}.traffic-chart>div{flex:1;text-align:center}.traffic-chart span{display:block;background:#8ccfcb;border-radius:4px 4px 0 0}.traffic-chart small{display:block;font-size:9px;margin-top:8px}.pages-heading{font-size:15px;margin:30px 0 15px}.page-row{display:flex;justify-content:space-between;gap:15px;font-size:12px;padding:13px 0;border-bottom:1px solid var(--line)}.empty{padding:24px 0;font-size:13px;color:var(--muted-ink)}.bookings-list{margin-top:24px}.table-scroll{overflow-x:auto}table{width:100%;border-collapse:collapse;text-align:left;font-size:12px}th{font-size:10px;color:var(--muted-ink);font-weight:500}th,td{padding:14px 10px;border-bottom:1px solid var(--line);vertical-align:top}td small{display:block;color:var(--muted-ink);font-size:10px;line-height:1.8;max-width:300px;white-space:pre-wrap;overflow-wrap:anywhere;margin-top:5px}.status{font-size:10px;background:var(--panel);padding:6px 9px;border-radius:99px}.status.confirmed{background:#8ccfcb35}.edit-button{border:0;background:transparent;color:var(--fill-accent);white-space:nowrap}details{margin-top:15px;font-size:12px}button:disabled{opacity:.5}@media(max-width:1000px){.admin-grid{grid-template-columns:1fr}.metrics{grid-template-columns:1fr 1fr}}@media(max-width:600px){.admin-panel{padding:35px 5%}.admin-top{align-items:flex-start}.admin-top h1{font-size:34px}.metrics{gap:10px}.metrics>div{padding:18px}.metrics strong{font-size:34px}.admin-card{padding:18px}.admin-calendar button{min-height:59px}.admin-calendar small{font-size:7px}.fields{grid-template-columns:1fr}.legend{gap:10px}.card-heading h2{font-size:20px}}
</style>
